      ...previousEditor,
      systemKey: component.systemKey,
      name: component.name,
      diameterMm: numberOr(geometry.diameterMm, previousEditor.diameterMm),
      startX: first.x,
      startY: first.y,
      startZ: first.z,
      endX: last.x,
      endY: last.y,
      endZ: last.z,
      estimatedLengthM: roundLength(distanceBetweenPoints(first, last)),
    };
