    setBuilding({ ...DEFAULT_BUILDING, ...(draft.buildingInputs as Partial<BuildingInputs>) });
    setSystems({ ...DEFAULT_SYSTEMS, ...(draft.systemInputs as Partial<SystemInputs>) });
