function templateDimensionLabel(key: string): string {
  const labels: Record<string, string> = {
    widthM: '宽',
    depthM: '深',
    heightM: '高',
    lengthM: '长',
    thicknessMm: '厚',
    sillHeightM: '离地',
    areaM2: '面积',
    diameterMm: '管径',
    widthMm: '宽',
    heightMm: '高',
    estimatedLengthM: '长度',
    floor: '楼层',
    installHeight: '安装高',
    material: '材质',
    openingDirection: '方向',
    modelSku: '型号',
    installMethod: '安装',
    nominalCapacityKw: '容量',
    designCoolingLoadKw: '冷负荷',
    designHeatingLoadKw: '热负荷',
  };
  return labels[key] ?? key;
