      widthMm: '宽',
      heightMm: '高',
      estimatedLengthM: '长度',
      floor: '楼层',
      installHeight: '安装高',
      material: '材质',
      openingDirection: '方向',
      modelSku: '型号',
      installMethod: '安装',
      nominalCapacityKw: '容量',
      designCoolingLoadKw: '冷负荷',
      designHeatingLoadKw: '热负荷',
    };
    return labels[key] ?? key;
