  if (/displayName/i.test(message)) return '中文名称不能为空，且长度不能超过 120 个字符。';
  if (/visibility/i.test(message)) return '显示状态只能是显示或隐藏。';
  if (/locked|lockState/i.test(message)) return '锁定状态只能是锁定或解锁。';
