    ['位置X', editor.x],
    ['位置Y', editor.y],
    ['位置Z', editor.z],
    ['标高', editor.elevation],
    ['安装高度', editor.installHeight],
    ['旋转X', editor.rotationX],
    ['旋转Y', editor.rotationY],
    ['旋转Z', editor.rotationZ],
